mapper.select:
select count(distinct bc.mother_rabbit_id) from breeding_cycles bc inner join rabbits r on r.id = bc.mother_rabbit_id and r.house_id = bc.house_id where bc.house_id in and bc.closed_at is null
and bc.batch_id = #{batchId}
and bc.mating_date is not null and r.is_active = true and r.type = '0' and r.gender = '0'

select month(birth_date) as month, coalesce(sum(live_kits), 0) as count
from parturition_records
where house_id in 

  and batch_id = #{batchId}

  and birth_date >= #{from}
  and birth_date < #{to}
group by month(birth_date)
order by month(birth_date)

select month(weaning_date) as month, coalesce(sum(weaning_count), 0) as count
from weaning_records
where house_id in 

  and batch_id = #{batchId}

  and weaning_date >= #{from}
  and weaning_date < #{to}
group by month(weaning_date)
order by month(weaning_date)
